import os
import torch


class Config:
    """
    Configuration for Idea 8: High-Resolution Multi-Task Network with Stable Focal Optimization.
    """

    # ==========================================
    # Paths & Directories
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_8"

    # Metadata Files (Generated by previous pipeline steps)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Output Paths
    MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    # Submission file typically goes to the root or specified output dir
    SUBMISSION_PATH = "submission.csv"

    # ==========================================
    # Data Configuration
    # ==========================================
    # High resolution is critical for detecting microcalcifications
    IMAGE_SIZE = (1024, 1024)

    # ==========================================
    # Model Architecture
    # ==========================================
    # EfficientNetV2-Small: Good balance of parameter efficiency and performance
    # 'tf_efficientnetv2_s.in21k_ft_in1k' indicates pre-training on ImageNet-21k
    # and fine-tuning on ImageNet-1k
    MODEL_NAME = "tf_efficientnetv2_s.in21k_ft_in1k"

    # Primary Head
    NUM_CLASSES = 1  # Binary classification for Cancer

    # Auxiliary Heads (Multi-Task Learning)
    USE_AUX_HEADS = True
    NUM_BIRADS_CLASSES = 3  # Labels: 0, 1, 2
    NUM_DENSITY_CLASSES = 4  # Labels: A, B, C, D

    # Metadata Fusion
    META_EMBED_DIM = 64

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42

    # Batch Size & Gradient Accumulation
    # Target effective batch size = 32
    # With 1024x1024 resolution on A100 40GB, we use a smaller physical batch
    BATCH_SIZE = 8
    GRAD_ACCUMULATION_STEPS = 4

    # Optimization
    NUM_EPOCHS = 10
    LEARNING_RATE = 2e-4
    WEIGHT_DECAY = 1e-2
    MAX_GRAD_NORM = 10.0

    # Scheduler (OneCycleLR settings)
    PCT_START = 0.1
    DIV_FACTOR = 25.0
    FINAL_DIV_FACTOR = 100.0

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 3

    # ==========================================
    # Loss Function (Focal Loss)
    # ==========================================
    # Parameters for Stable Focal Optimization to handle class imbalance
    # without the instability of high pos_weight values
    FOCAL_ALPHA = 0.25
    FOCAL_GAMMA = 2.0

    # ==========================================
    # Hardware & Compute
    # ==========================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    # 12 vCPUs available
    NUM_WORKERS = 4

    # ==========================================
    # Debugging / Development
    # ==========================================
    # Set DEBUG to True to run on a small subset of data for quick iteration
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 500

    @classmethod
    def setup(cls):
        """
        Initializes the working directory and prints configuration status.
        Should be called at the start of the pipeline.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        print(f"Config Setup Complete.")
        print(f"Working Directory: {cls.WORKING_DIR}")
        print(f"Device: {cls.DEVICE}")
        print(f"Image Size: {cls.IMAGE_SIZE}")
        print(f"Effective Batch Size: {cls.BATCH_SIZE * cls.GRAD_ACCUMULATION_STEPS}")
